mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;log=[]
def gettok():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b""));tok=json.load(r)["token"];return
        except urllib.error.HTTPError as e:
            w=float(e.headers.get("Retry-After") or 1);time.sleep(w)
def get(p):
    global tok
    if not tok: gettok()
    for a in range(200):
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30))
        except urllib.error.HTTPError as e:
            log.append((p,e.code))
            if e.code==401: gettok()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404 and p.startswith("/customers"): return None
            else: time.sleep(0.5)
        except Exception as e: log.append((p,str(e)));time.sleep(0.5)
    raise SystemExit("fail "+p)
orders={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in orders: dups+=1
        else: orders[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=set()
for o in orders.values():
    if o["status"]!="shipped": odd.add(o["status"]) if o["status"] not in("placed","cancelled","returned") else None;continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: t=t.replace(tzinfo=timezone.utc);odd.add("naive_ts")
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.add(f"missing cust {c}");continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;n+=1
json.dump({"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(pages,len(orders),dups,n,reg,odd,sorted({c for _,c in log},key=str))
from collections import Counter;print(Counter(o["status"] for o in orders.values()))
EOF
python3 -I /tmp/work/r.py; cat /workspace/result.json

